const script = `
import { WorkflowEntrypoint } from "cloudflare:workers";
export class SecretFlow extends WorkflowEntrypoint {
  async run(event, step) {
    let secret;
    try {
      secret = await step.do("sensitive step", { sensitive: "output" }, async () => ({ token: "super-secret" }));
    } catch (e) {
      return { rejected: String((e && e.message) || e) };
    }
    const seen = await step.do("downstream step", async () => secret.token);
    return { seen };
  }
}
export default {
  async fetch(req, env) {
    const url = new URL(req.url);
    if (url.pathname === "/create") { const i = await env.WF.create(); return new Response(i.id); }
    const i = await env.WF.get(url.searchParams.get("id"));
    return Response.json(await i.status());
  }
};`;
(async () => {
  const mf = new Miniflare({
    modules: true, script, compatibilityDate: "2025-01-01",
    workflows: { WF: { name: "secret-flow", className: "SecretFlow" } },
  });
  const id = await (await mf.dispatchFetch("http://localhost/create")).text();
  let st;
  for (let n = 0; n < 200; n++) {
    st = await (await mf.dispatchFetch("http://localhost/status?id=" + encodeURIComponent(id))).json();
    if (st.status === "complete" || st.status === "errored" || st.status === "terminated") break;
    await new Promise(r => setTimeout(r, 250));
  }
  const out = st && st.output;
  console.log("status: " + JSON.stringify(st));
